async function api(path,body,method){const verb=method||(body?'POST':'GET'),serialized=body?JSON.stringify(body):undefined;let slot,key;if(body){const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verb+' '+path+' '+serialized));slot='wentian-commerce-outbox:'+Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');key=sessionStorage.getItem(slot)||crypto.randomUUID();sessionStorage.setItem(slot,key)}const response=await fetch('/api/commerce/'+path,{method:verb,headers:body?{'content-type':'application/json','idempotency-key':key}:{},body:serialized});const value=await response.json();if(!response.ok){if(response.status<500)sessionStorage.removeItem(slot);throw new Error((value.error?.message||t('error'))+' ['+(value.error?.code||response.status)+']')}if(slot)sessionStorage.removeItem(slot);return value}
async function load(){catalog=(await api('catalog')).listings;try{data=await api('dashboard');authenticated=true}catch{authenticated=false;data.parts=(await api('parts')).parts}render()}
function render(){const renderStarted=performance.now();document.documentElement.lang=lang;$('language').value=lang;document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));$('tabs').innerHTML=['market','business','projects','sites','orders','builder','operations'].map(x=>'<button role="tab" aria-selected="'+(tab===x)+'" data-action="tab" data-id="'+x+'">'+esc(t(x))+'</button>').join('');const login=!authenticated&&tab!=='market'&&tab!=='builder'?'<p><a href="/workbench">'+esc(t('login'))+' ↗</a></p>':'';$('view').innerHTML=login+views[tab]();applyLayout();if(tab==='builder'&&$('evaluation'))$('evaluation').dataset.updateMs=String(performance.now()-renderStarted);}
