const sitesView=views.sites;views.sites=()=>sitesView()+data.sites.map(site=>{const revision=site.revisions.at(-1);return card(site.title+' / '+t('pages'),'<details><summary>'+esc(t('pages'))+'</summary>'+form('sitePages',sitePageSlugs.map((slug,index)=>{const page=revision.pages?.[slug]||{};return '<h3>'+esc(t(extraKeys[index+4]))+'</h3>'+field('title','page_'+slug+'_title','text',page.title||slug)+area('content','page_'+slug+'_body',page.body||'')+field('source','page_'+slug+'_source','text',page.source||'')}).join('')+'<label><input type="checkbox" name="pagesConfirmed" required style="width:auto"> '+esc(t('confirmed'))+'</label>',site.id)+'</details>'+form('siteDiff',select('version','from',site.revisions.map(r=>[r.revision,'v'+r.revision]))+select('version','to',site.revisions.map(r=>[r.revision,'v'+r.revision])),site.id))}).join('');

